For each warehouse with a value less than 10000, add the square of the stock divided by 10 to the demand. Then return 10000 plus the sum of all demands divided by 100.
```python
#include <iostream>
#include <vector>
#include <cmath>

// Function to calculate a sum based on the input
double f(int n, std::vector<std::tuple<int, int, int>>& warehouses) {
    // Calculate the sum of the calculated demands
  double sum = 0;
  for (auto& warehouse: warehouses) {
    if (std::get<2>(warehouse) < 10000) {
      double demand = std::get<0>(warehouse) + std::pow(std::get<1>(warehouse), 2) / 10.0;
      sum += demand;
    }
  }
  // Return 10000 plus the sum of all calculated demands divided by 100
  return 10000 + sum / 100.0;
}
```

